"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";

import { Search, X } from "lucide-react";
import {
  useEffect,
  useLayoutEffect,
  useId,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { Button } from "./button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
  type DialogContentProps,
} from "./dialog";
import { Input } from "./input";
import { cn } from "./lib/cn";
import "./command-palette.css";

export type CommandItem = {
  id: string;
  label: string;
  description?: string;
  group?: string;
  icon?: ReactNode;
  keywords?: readonly string[];
  disabled?: boolean;
  /** One disambiguating fact on the right, in mono: an amount, a role, a shortcut. */
  meta?: string;
  /** Shown in the side pane while the item is highlighted. */
  preview?: CommandPreview;
  onSelect: () => void;
};

export type CommandPreview = {
  kind: string;
  title: string;
  rows?: readonly (readonly [string, string])[];
  hint?: string;
};

/** Typing the prefix narrows the list to one group, shown as a chip. */
export type CommandScope = { prefix: string; label: string; group: string };

export type CommandPaletteProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: readonly CommandItem[];
  title?: string;
  description?: string;
  className?: string;
  onCloseAutoFocus?: DialogContentProps["onCloseAutoFocus"];
  scopes?: readonly CommandScope[];
  /** Offered when nothing matches, e.g. create an invoice for the typed name. */
  emptyAction?: { label: (query: string) => string; onSelect: (query: string) => void };
  /** The search field's prompt, naming what can be found, e.g. "Search people, companies and deals…". */
  placeholder?: string;
  /** What one item is called in the count and the empty state, singular and plural: ["result", "results"] for a site search. */
  noun?: readonly [string, string];
};

export function CommandPalette({
  open,
  onOpenChange,
  items,
  title = "Command palette",
  description = "Search destinations, projects, and actions.",
  className,
  onCloseAutoFocus,
  scopes = [],
  emptyAction,
  placeholder = "Find a project or action…",
  noun = ["command", "commands"],
}: CommandPaletteProps) {
  const hasPreview = items.some((item) => item.preview);
  // Esc leaves an active scope first; without a scope it closes.
  const clearOnEscape = useRef<(() => boolean) | null>(null);
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className={cn(
          "flex flex-col gap-0 overflow-hidden rounded-[16px] p-0 sm:p-0",
          hasPreview ? "max-w-2xl" : "max-w-xl",
          className,
        )}
        onCloseAutoFocus={onCloseAutoFocus}
        onEscapeKeyDown={(event) => {
          if (clearOnEscape.current?.()) event.preventDefault();
        }}
      >
        <PaletteContent
          items={items}
          title={title}
          description={description}
          interactive={open}
          scopes={scopes}
          emptyAction={emptyAction}
          placeholder={placeholder}
          noun={noun}
          hasPreview={hasPreview}
          clearOnEscape={clearOnEscape}
          onSelect={(item) => {
            onOpenChange(false);
            item.onSelect();
          }}
        />
      </DialogContent>
    </Dialog>
  );
}

function PaletteContent({
  items,
  title,
  description,
  interactive,
  onSelect,
  scopes,
  emptyAction,
  placeholder,
  noun,
  hasPreview,
  clearOnEscape,
}: {
  items: readonly CommandItem[];
  title: string;
  description: string;
  interactive: boolean;
  onSelect: (item: CommandItem) => void;
  scopes: readonly CommandScope[];
  emptyAction?: CommandPaletteProps["emptyAction"];
  placeholder: string;
  noun: readonly [string, string];
  hasPreview: boolean;
  clearOnEscape: { current: (() => boolean) | null };
}) {
  const id = useId();
  const input = useRef<HTMLInputElement>(null);
  const activeOption = useRef<HTMLDivElement>(null);
  const options = useRef<HTMLDivElement>(null);
  const [highlight, setHighlight] = useState<{
    top: number;
    height: number;
  } | null>(null);
  const [query, setQuery] = useState("");
  const [activeId, setActiveId] = useState<string | null>(null);
  const [scopeId, setScopeId] = useState<string | null>(null);
  const scope = scopes.find((candidate) => candidate.prefix === scopeId);
  const search = query.trim().toLowerCase();
  const showIcons = items.some((item) => Boolean(item.icon));
  const groups = new Map<string, CommandItem[]>();
  for (const item of items) {
    const group = item.group ?? "";
    if (scope && group !== scope.group) continue;
    const grouped = groups.get(group) ?? [];
    groups.set(group, grouped);
    const text = [item.label, item.description, ...(item.keywords ?? [])]
      .join(" ")
      .toLowerCase();
    if (text.includes(search)) grouped.push(item);
  }
  const visibleGroups = [...groups.entries()].filter(
    ([, commands]) => commands.length,
  );
  const matched = visibleGroups.flatMap(([, commands]) => commands);
  const enabled = matched.filter((item) => !item.disabled);
  const active = enabled.find((item) => item.id === activeId) ?? enabled[0];
  const optionIds = new Map(
    matched.map((item, index) => [item.id, `${id}-option-${index}`]),
  );
  const listId = `${id}-commands`;

  useEffect(() => {
    activeOption.current?.scrollIntoView({
      block: "nearest",
      behavior: "instant",
    });
  }, [active?.id, search]);

  useLayoutEffect(() => {
    const list = options.current;
    const option = activeOption.current;
    if (!list || !option) {
      setHighlight(null);
      return;
    }
    const measure = () => {
      setHighlight({
        top: option.offsetTop,
        height: option.offsetHeight,
      });
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(list);
    observer.observe(option);
    return () => observer.disconnect();
  }, [active?.id, search]);

  function select(item: CommandItem) {
    if (interactive && !item.disabled) onSelect(item);
  }

  useEffect(() => {
    clearOnEscape.current = () => {
      if (!scope) return false;
      setScopeId(null);
      setActiveId(null);
      return true;
    };
  });

  function mark(text: string) {
    const at = search ? text.toLowerCase().indexOf(search) : -1;
    if (at < 0) return text;
    return (
      <>
        {text.slice(0, at)}
        <mark data-slot="command-match">{text.slice(at, at + search.length)}</mark>
        {text.slice(at + search.length)}
      </>
    );
  }

  function clearSearch() {
    setQuery("");
    setScopeId(null);
    setActiveId(null);
    input.current?.focus();
  }

  return (
    <>
      <div className="shrink-0 border-b border-border p-4">
        <DialogTitle className="pr-12 text-sm leading-5">{title}</DialogTitle>
        <DialogDescription className="sr-only">{description}</DialogDescription>
        <label htmlFor={`${id}-search`} className="sr-only">
          Search {noun[1]}
        </label>
        <div className="relative mt-3 flex items-center gap-2 rounded-surface bg-surface pl-3 focus-within:outline-solid focus-within:outline-2 focus-within:outline-offset-2 focus-within:outline-ring">
          <Search
            className="pointer-events-none size-4 shrink-0 text-muted-foreground"
            aria-hidden="true"
          />
          {scope && <span data-slot="command-scope">{scope.label}</span>}
          <Input
            ref={input}
            id={`${id}-search`}
            role="combobox"
            aria-autocomplete="list"
            aria-expanded={interactive}
            aria-controls={listId}
            aria-activedescendant={
              active ? optionIds.get(active.id) : undefined
            }
            autoComplete="off"
            spellCheck={false}
            placeholder={placeholder}
            value={query}
            readOnly={!interactive}
            className="flex-1 border-0 bg-transparent pl-0 pr-11 shadow-none focus-visible:shadow-none"
            onChange={(event) => {
              if (!interactive) return;
              const value = event.target.value;
              // Typing a scope prefix first turns it into a chip.
              const typed = !scope && scopes.find((candidate) => value.startsWith(candidate.prefix));
              if (typed) {
                setScopeId(typed.prefix);
                setQuery(value.slice(typed.prefix.length));
              } else {
                setQuery(value);
              }
              setActiveId(null);
            }}
            onKeyDown={(event) => {
              if (event.key === "Backspace" && !query && scope) {
                event.preventDefault();
                setScopeId(null);
                return;
              }
              if (
                !interactive ||
                event.nativeEvent.isComposing ||
                event.altKey ||
                event.ctrlKey ||
                event.metaKey ||
                event.shiftKey
              )
                return;
              if (event.key === "Enter" && active) {
                event.preventDefault();
                select(active);
              } else if (
                enabled.length &&
                (["ArrowDown", "ArrowUp"].includes(event.key) ||
                  (!query && ["Home", "End"].includes(event.key)))
              ) {
                event.preventDefault();
                const current = enabled.findIndex(
                  (item) => item.id === active?.id,
                );
                const next =
                  event.key === "Home"
                    ? 0
                    : event.key === "End"
                      ? enabled.length - 1
                      : (current +
                          (event.key === "ArrowDown" ? 1 : -1) +
                          enabled.length) %
                        enabled.length;
                setActiveId(enabled[next].id);
              }
            }}
          />
          {query && (
            <Button
              variant="ghost"
              size="icon"
              className="absolute top-0 right-0"
              aria-label="Clear command search"
              onClick={clearSearch}
            >
              <X className="size-4" aria-hidden="true" />
            </Button>
          )}
        </div>
      </div>

      <div className={cn("grid min-h-0", hasPreview && "md:grid-cols-[minmax(0,1fr)_240px]")}>
      <div className="min-h-0 max-h-[min(28rem,60dvh)] overflow-y-auto overscroll-contain p-2">
        <div
          ref={options}
          id={listId}
          role="listbox"
          aria-label="Commands"
          className="relative isolate"
        >
          {highlight && (
            <div
              key={search}
              data-slot="command-highlight"
              aria-hidden="true"
              style={{
                height: highlight.height,
                transform: `translateY(${highlight.top}px)`,
              }}
            />
          )}
          {visibleGroups.map(([group, commands], groupIndex) => (
            <div key={group} role="group" aria-label={group || undefined}>
              {group && (
                <p
                  className={cn(
                    "px-3 pb-1 text-xs font-medium text-muted-foreground",
                    groupIndex ? "pt-3" : "pt-1",
                  )}
                >
                  {group}
                </p>
              )}
              {commands.map((item) => {
                const selected = active?.id === item.id;
                return (
                  <div
                    data-slot="command-option"
                    key={item.id}
                    id={optionIds.get(item.id)}
                    ref={selected ? activeOption : undefined}
                    role="option"
                    aria-selected={selected}
                    aria-disabled={item.disabled || undefined}
                    className={cn(
                      "flex min-h-[var(--control-height)] cursor-pointer items-center gap-3 rounded-surface px-3 text-sm font-medium",
                      item.description && "py-2",
                      "text-foreground",
                      item.disabled &&
                        "cursor-not-allowed text-muted-foreground hover:bg-transparent",
                    )}
                    onMouseDown={(event) => event.preventDefault()}
                    onMouseEnter={() => {
                      if (!item.disabled && interactive) setActiveId(item.id);
                    }}
                    onClick={() => select(item)}
                  >
                    {showIcons && (
                      <span
                        className="flex size-5 shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-4"
                        aria-hidden="true"
                      >
                        {item.icon}
                      </span>
                    )}
                    <span className="min-w-0 flex-1">
                      <span className="block text-sm leading-5 font-medium break-words [overflow-wrap:anywhere]">
                        {mark(item.label)}
                      </span>
                      {item.description && (
                        <span className="block text-xs leading-4 text-muted-foreground break-words [overflow-wrap:anywhere]">
                          {item.description}
                        </span>
                      )}
                    </span>
                    {item.meta && !item.disabled && (
                      <span className="shrink-0 tabular-nums text-xs text-muted-foreground">
                        {item.meta}
                      </span>
                    )}
                    {item.disabled && (
                      <span className="shrink-0 text-xs text-muted-foreground">
                        Unavailable
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          ))}
        </div>
        {!matched.length && (
          <div className="px-3 py-6 text-center">
            <p className="text-sm font-medium">No {noun[1]} found</p>
            <p className="mt-1 text-xs leading-5 text-muted-foreground break-words [overflow-wrap:anywhere]">
              {search
                ? `Nothing matches “${query.trim()}”. Try another word or a shorter one.`
                : `There are no ${noun[1]} in this context.`}
            </p>
            {search && (
              <div className="mt-4 flex flex-wrap justify-center gap-2">
                {emptyAction && (
                  <Button
                    variant="default"
                    size="sm"
                    onClick={() => emptyAction.onSelect(search)}
                  >
                    {emptyAction.label(search)}
                  </Button>
                )}
                <Button variant="secondary" size="sm" onClick={clearSearch}>
                  Clear search
                </Button>
              </div>
            )}
          </div>
        )}
      </div>
      {hasPreview && (
        <div data-slot="command-preview" aria-live="polite" className="hidden md:flex">
          {active?.preview ? (
            <>
              <span className="tabular-nums text-[11px] tracking-[0.06em] text-muted-foreground uppercase">{active.preview.kind}</span>
              <span className="text-base leading-6 font-semibold">{active.preview.title}</span>
              {active.preview.rows && (
                <dl className="grid grid-cols-[72px_minmax(0,1fr)] gap-x-2.5 gap-y-1.5 text-[13px] leading-[18px]">
                  {active.preview.rows.map(([key, value]) => (
                    <div key={key} className="contents">
                      <dt className="text-muted-foreground">{key}</dt>
                      <dd className="m-0 tabular-nums">{value}</dd>
                    </div>
                  ))}
                </dl>
              )}
              {active.preview.hint && <span className="mt-auto text-xs text-muted-foreground">{active.preview.hint}</span>}
            </>
          ) : (
            <span className="text-xs text-muted-foreground">Highlight a result to preview it.</span>
          )}
        </div>
      )}
      </div>

      <div className="flex shrink-0 flex-wrap items-center justify-between gap-x-4 gap-y-1 border-t border-border px-4 py-3 text-xs leading-5 text-muted-foreground">
        <p role="status" aria-atomic="true">
          {matched.length} {matched.length === 1 ? noun[0] : noun[1]}
        </p>
        <p className="hidden sm:block">
          <span aria-hidden="true">↑↓</span> Navigate · Enter Select · Esc Close
        </p>
      </div>
    </>
  );
}

"use client";

import * as DialogPrimitive from "@radix-ui/react-dialog";
import { X } from "lucide-react";
import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import { Button } from "./button";
import "./shared/dialog-overlay.css";
import "./dialog.css";

export const Dialog = DialogPrimitive.Root;
export const DialogTrigger = DialogPrimitive.Trigger;
export const DialogClose = DialogPrimitive.Close;

export type DialogContentProps = ComponentProps<
  typeof DialogPrimitive.Content
> & {
  showCloseButton?: boolean;
};

export function DialogContent({
  className,
  children,
  showCloseButton = true,
  ...props
}: DialogContentProps) {
  return (
    <DialogPrimitive.Portal>
      <DialogPrimitive.Overlay
        data-slot="dialog-overlay"
        className="fixed inset-0 z-50 bg-[var(--overlay)]"
      />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          "fixed top-1/2 left-1/2 z-50 grid max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 gap-5 overflow-y-auto rounded-[20px] border border-border bg-elevated p-5 text-foreground shadow-overlay outline-none sm:p-6",
          // Phones: the dialog becomes a sheet resting on the bottom edge.
          props["data-motion" as keyof typeof props] !== "sheet" &&
            "max-sm:top-auto max-sm:bottom-2 max-sm:left-2 max-sm:w-[calc(100%-1rem)] max-sm:max-w-none max-sm:translate-x-0 max-sm:translate-y-0 max-sm:max-h-[calc(100dvh-1.5rem)]",
          className,
        )}
        {...props}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close asChild>
            <Button
              variant="ghost"
              size="icon"
              className="absolute top-3.5 right-3.5 size-8 rounded-control max-sm:size-11"
              aria-label="Close dialog"
            >
              <X aria-hidden="true" />
            </Button>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPrimitive.Portal>
  );
}

export function DialogHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn("flex min-w-0 flex-col gap-2 pr-8", className)}
      {...props}
    />
  );
}

export function DialogFooter({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "sticky bottom-[-1.25rem] z-10 -mx-5 -mb-5 flex flex-col-reverse gap-2 border-t border-border bg-[var(--elevated-glass)] px-4 py-3.5 sm:bottom-[-1.5rem] sm:-mx-6 sm:-mb-6 sm:flex-row sm:justify-end",
        className,
      )}
      {...props}
    />
  );
}

export function DialogTitle({
  className,
  ...props
}: ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      className={cn(
        "text-base leading-6 font-semibold tracking-tight break-words",
        className,
      )}
      {...props}
    />
  );
}

export function DialogDescription({
  className,
  ...props
}: ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      className={cn("text-sm leading-5 text-muted-foreground", className)}
      {...props}
    />
  );
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import "./shared/input.css";
import "./shared/input-2.css";
import "./shared/input-group.css";
import "./input.css";

const fieldText =
  "w-full min-w-0 text-base text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed md:text-sm";

export type InputProps = ComponentProps<"input"> & {
  /** Fixed text or an icon before the value, e.g. "caliper.app/". */
  leading?: ReactNode;
  /** Text, an icon or a status after the value, e.g. a spinner or a count. */
  trailing?: ReactNode;
};

/**
 * A recessed text field. Fields sit slightly below the paper (an inner shade
 * and a 3:1 ring); buttons stand on it, so what you fill and what you press
 * never look alike.
 */
export function Input({ className, leading, trailing, ...props }: InputProps) {
  if (leading === undefined && trailing === undefined) {
    return (
      <input
        data-slot="input"
        className={cn("flex h-[var(--control-height)] rounded-button px-3", fieldText, className)}
        {...props}
      />
    );
  }
  return (
    <span
      data-slot="input-group"
      data-disabled={props.disabled || undefined}
      data-invalid={props["aria-invalid"] === true || props["aria-invalid"] === "true" || undefined}
      data-readonly={props.readOnly || undefined}
      className={cn("flex h-[var(--control-height)] w-full min-w-0 items-center gap-2 rounded-button px-3", className)}
    >
      {leading !== undefined && <span data-slot="input-affix">{leading}</span>}
      <input data-slot="input-bare" className={cn("h-full flex-1 bg-transparent", fieldText)} {...props} />
      {trailing !== undefined && <span data-slot="input-trailing">{trailing}</span>}
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

